import type { DialogProps } from "./dialog.types";

import React, { forwardRef, useEffect, useState } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixDialog from "@radix-ui/react-dialog";
import { Close as CloseIcon } from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";

import { DialogClasses, StyledDialog, StyledDialogOverlay } from "./dialog.styles";

const DialogRoot = forwardRef<HTMLDivElement, DialogProps>(
  (
    {
      className,
      children,
      onOpenChange,
      dismissible = true,
      open,
      defaultOpen = false,
      containerElement,
      modal = false,
      variant = "default",
      onEscapeKeyDown,
      onInteractOutside,
      onPointerDownOutside,
      onOpenAutoFocus,
      onCloseAutoFocus,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(DialogClasses.root, className);
    const [portalContainer, setPortalContainer] = useState<HTMLElement | Element | null>(null);

    useEffect(() => {
      // Set the portal container to the provided containerElement, if not provided then
      // fallback to the top level ThemeProvider element or body
      const el = document.body.querySelector(`[data-textura-theme-provider="true"]`);
      setPortalContainer(containerElement || el || document.body);
    }, [containerElement]);

    const { trigger, content, closeIconButton } = getValidDialogChildren(children);

    return (
      <RadixDialog.Root
        defaultOpen={defaultOpen}
        modal={modal}
        open={open}
        onOpenChange={onOpenChange}
      >
        {trigger}
        <RadixDialog.Portal container={portalContainer}>
          <StyledDialogOverlay
            className={DialogClasses.overlay}
            currentTheme={theme}
            styleSlots={props.styleSlots}
            variant={variant}
          />
          <StyledDialog
            ref={ref}
            aria-describedby={undefined}
            className={clsx(rootClasses, DialogClasses.body)}
            currentTheme={theme}
            variant={variant}
            onCloseAutoFocus={onCloseAutoFocus}
            onEscapeKeyDown={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onEscapeKeyDown?.(e);
            }}
            onInteractOutside={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onInteractOutside?.(e);
            }}
            onOpenAutoFocus={onOpenAutoFocus}
            onPointerDownOutside={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onPointerDownOutside?.(e);
            }}
            {...props}
          >
            {content}
            {closeIconButton}
          </StyledDialog>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    );
  },
);
DialogRoot.displayName = "Dialog";

const Title = ({ className, children, ...props }: RadixDialog.DialogTitleProps) => (
  <RadixDialog.Title
    className={clsx(DialogClasses.title, className)}
    data-dialog-type="title"
    {...props}
  >
    {children}
  </RadixDialog.Title>
);
Title.displayName = "Dialog.Title";

const Trigger = ({ children, ...props }: RadixDialog.DialogTriggerProps) => {
  return (
    <RadixDialog.Trigger data-dialog-type="trigger" {...props} asChild>
      {children}
    </RadixDialog.Trigger>
  );
};
Trigger.displayName = "Dialog.Trigger";

const Close = ({ children, ...props }: RadixDialog.DialogCloseProps) => (
  <RadixDialog.Close data-dialog-type="close" {...props} asChild>
    {children}
  </RadixDialog.Close>
);
Close.displayName = "Dialog.Close";

const CloseIconButton = ({
  className,
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof RadixDialog.Close>) => (
  <RadixDialog.Close
    asChild
    aria-label={props["aria-label"] || "Close dialog"}
    className={clsx(DialogClasses.closeIconButton, className)}
    data-dialog-type="close-button"
    {...props}
  >
    <IconButton buttonType="secondary">{children || <CloseIcon />}</IconButton>
  </RadixDialog.Close>
);
CloseIconButton.displayName = "Dialog.CloseIconButton";

const Content = ({ className, children, ...props }: React.ComponentPropsWithoutRef<"div">) => (
  <div className={clsx(DialogClasses.content, className)} data-dialog-type="content" {...props}>
    {children}
  </div>
);
Content.displayName = "Dialog.Content";

const Footer = ({ className, children, ...props }: React.ComponentPropsWithoutRef<"div">) => (
  <footer className={clsx(DialogClasses.footer, className)} data-dialog-type="footer" {...props}>
    {children}
  </footer>
);
Footer.displayName = "Dialog.Footer";

const Dialog = Object.assign(DialogRoot, {
  Trigger,
  Close,
  CloseIconButton,
  Title,
  Content,
  Footer,
});

export default Dialog;

/**
 * Utility function to validate and extract Dialog children
 * @param {React.ReactNode} children - The children of the Dialog component
 * @returns {Object} - An object containing the trigger, content, and closeIconButton elements
 * @throws Will throw an error if the validation fails
 */
const getValidDialogChildren = (
  children: React.ReactNode,
): {
  trigger: React.ReactNode[];
  content: React.ReactNode[];
  closeIconButton: React.ReactNode[];
} => {
  let titleCount = 0;
  let closeIconButtonCount = 0;
  let triggerCount = 0;
  let contentCount = 0;
  let footerCount = 0;

  const trigger: React.ReactNode[] = [];
  const content: React.ReactNode[] = [];
  const closeIconButton: React.ReactNode[] = [];

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;

      if (displayName !== "Dialog.Trigger" && displayName !== "Dialog.CloseIconButton") {
        content.push(child);
      }

      if (displayName === "Dialog.Content") {
        contentCount++;
      } else if (displayName === "Dialog.Footer") {
        footerCount++;
      } else if (displayName === "Dialog.Title") {
        titleCount++;
      } else if (displayName === "Dialog.Trigger") {
        trigger.push(child);
        triggerCount++;
      } else if (displayName === "Dialog.CloseIconButton") {
        closeIconButton.push(child);
        closeIconButtonCount++;
      } else {
        throw new Error(
          "<Dialog> only accepts <Dialog.Title>, <Dialog.CloseIconButton>, <Dialog.Trigger>, <Dialog.Content>, and <Dialog.Footer> as children.",
        );
      }
    }
  });

  if (contentCount > 1)
    throw new Error(`<Dialog> can only have one <Dialog.Content>. Found ${contentCount}.`);

  if (closeIconButtonCount > 1)
    throw new Error(
      `<Dialog> can only have one <Dialog.CloseIconButton>. Found ${closeIconButtonCount}.`,
    );
  if (footerCount > 1)
    throw new Error(`<Dialog> can only have one <Dialog.Footer>. Found ${footerCount}.`);
  if (titleCount > 1)
    throw new Error(`<Dialog> can only have one <Dialog.Title>. Found ${titleCount}.`);
  if (triggerCount > 1)
    throw new Error(`<Dialog> can only have one <Dialog.Trigger>. Found ${triggerCount}.`);

  return { trigger, content, closeIconButton };
};
